#!/bin/bash
# contra_build.sh - AUTO-GENERATED by compose_contra.py. Edit game/contra/*.cs, re-run composer; never hand-edit.
set -e
UNITY=/content/ue/Editor/Unity
DEMO=/content/work/demo
PROJ=/content/work/runandgun
BUNDLE=$PROJ/Builds/WebGL/probe

echo "=== PREFLIGHT ==="
test -f /content/unity_bin.txt || { echo NO_UNITY_BIN; exit 6; }
test -x "$UNITY" || { echo NO_EDITOR_BIN; exit 6; }
echo PREFLIGHT_OK

echo "=== PROJECT ==="
if [ ! -d "$PROJ/Assets" ]; then
  if [ -d "$DEMO/Assets" ]; then
    echo CLONE_FROM_DEMO
    rm -rf "$PROJ"
    cp -a "$DEMO" "$PROJ"
  else
    echo CREATE_PROJECT_FRESH
    rm -rf "$PROJ"
    "$UNITY" -batchmode -quit -nographics -createProject "$PROJ" -logFile /content/create_rag.log
    echo CREATE_DONE
  fi
fi
rm -rf "$PROJ/Assets/Demo" "$PROJ/Assets/Scenes" "$PROJ/Builds" "$PROJ/Temp"
test -d "$PROJ/Assets" || { echo NO_PROJECT; exit 6; }
mkdir -p "$PROJ/Assets/Editor" "$PROJ/Assets/Contra"

echo "=== ENSURE UGUI (bare -createProject lacks UnityEngine.UI) ==="
python3 - "$PROJ" <<'PYEOF'
import json, sys, os
p = os.path.join(sys.argv[1], 'Packages', 'manifest.json')
m = json.load(open(p))
m.setdefault('dependencies', {})
if 'com.unity.ugui' not in m['dependencies']:
    m['dependencies']['com.unity.ugui'] = '2.0.0'
    open(p, 'w').write(json.dumps(m, indent=2))
    print('UGUI_ADDED')
else:
    print('UGUI_PRESENT')
PYEOF
echo PROJECT_READY

cat > "$PROJ/Assets/Editor/BuildScript.cs" <<'CSEOF'
using System.IO; using System.Linq; using UnityEngine; using UnityEditor; using UnityEditor.SceneManagement;
public static class BuildScript {
    [MenuItem("Build/Perform")]
    public static void PerformBuild() {
        var scenes = new string[] { "Assets/Scenes/Sample.unity" };
        if (!File.Exists(scenes[0])) {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            System.IO.Directory.CreateDirectory("Assets/Scenes");
            EditorSceneManager.SaveScene(scene, scenes[0]);
            Debug.Log("SCENE_CREATED_BY_SCRIPT");
        }
        EditorBuildSettings.scenes = scenes.Select(s => new EditorBuildSettingsScene(s, true)).ToArray();
        AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        if (!File.Exists(scenes[0])) throw new System.Exception("SCENE_SAVE_FAILED: " + scenes[0]);
        var target = BuildTarget.WebGL; var outDir = "Builds/WebGL/probe";
        if (target == BuildTarget.WebGL) PlayerSettings.WebGL.compressionFormat = WebGLCompressionFormat.Disabled;
        var report = BuildPipeline.BuildPlayer(scenes, outDir, target, BuildOptions.None);
        if (report.summary.result != UnityEditor.Build.Reporting.BuildResult.Succeeded) throw new System.Exception("BUILD_FAILED: " + report.summary.result);
        Debug.Log("BUILD_OK " + report.summary.totalSize + " bytes");
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/Bullet2D.cs" <<'CSEOF'
using UnityEngine;

public class Bullet2D : MonoBehaviour {
    public Collider2D ignore;
    void Start() {
        Destroy(gameObject, 2f);
    }
    void OnTriggerEnter2D(Collider2D other) {
        if (other == ignore) return;
        var e = other.GetComponent<ContraEnemy>();
        if (e != null) e.Die();
        Destroy(gameObject);
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/ContraBoot.cs" <<'CSEOF'
using UnityEngine;
using UnityEngine.UI;

public static class GameSprites {
    public static Sprite White;
    public static Sprite Get() {
        if (White == null) {
            var tex = new Texture2D(4, 4, TextureFormat.RGBA32, false);
            var cols = new Color32[16];
            for (int i = 0; i < 16; i++) cols[i] = new Color32(255, 255, 255, 255);
            tex.SetPixels32(cols);
            tex.Apply();
            White = Sprite.Create(tex, new Rect(0f, 0f, 4f, 4f), new Vector2(0.5f, 0.5f), 4f);
            White.name = "WhiteSquare";
        }
        return White;
    }
}

public static class ContraBoot {
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    static void Boot() {
        var stale = GameObject.Find("Cube");
        if (stale != null) Object.Destroy(stale);
        Build();
    }

    // Re-callable after death reset (RuntimeInitializeOnLoadMethod only fires once per Play session,
    // so restart = destroy the ContraGame root + Build() again from ContraRestarter)
    public static void Build() {
        if (GameObject.Find("ContraGame") != null) return;
        var root = new GameObject("ContraGame");

        var camGo = new GameObject("MainCamera");
        camGo.transform.SetParent(root.transform, false);
        var cam = camGo.AddComponent<Camera>();
        cam.tag = "MainCamera";
        cam.orthographic = true;
        cam.orthographicSize = 6f;
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.08f, 0.09f, 0.16f);
        camGo.transform.position = new Vector3(0f, 1f, -10f);
        var fc = camGo.AddComponent<FollowCam>();
        fc.minX = -26f; fc.maxX = 26f;

        MakeBox(root.transform, "Ground", new Vector3(0f, -3.5f, 0f), new Vector3(80f, 1f, 1f), new Color(0.34f, 0.36f, 0.40f));
        MakeBox(root.transform, "WallL", new Vector3(-40f, 1f, 0f), new Vector3(1f, 14f, 1f), new Color(0f, 0f, 0f, 0f));
        MakeBox(root.transform, "WallR", new Vector3(40f, 1f, 0f), new Vector3(1f, 14f, 1f), new Color(0f, 0f, 0f, 0f));

        // Ascending terraces left-to-right; tier tops -1.1 / 0.8 / 2.6 (jump apex 2.16 m, clearance >= 0.26 m)
        // Adjacent edges (gaps 0-2 m) form a climbable catwalk route; tier 2 offset from walk lanes
        MakePlatform(root.transform, "PlatA", new Vector3(-16f, -1.3f, 0f), new Vector3(8f, 0.4f, 1f));
        MakePlatform(root.transform, "PlatB", new Vector3(-6f, -1.3f, 0f), new Vector3(8f, 0.4f, 1f));
        MakePlatform(root.transform, "PlatC", new Vector3(2f, 0.6f, 0f), new Vector3(8f, 0.4f, 1f));
        MakePlatform(root.transform, "PlatD", new Vector3(12f, 0.6f, 0f), new Vector3(8f, 0.4f, 1f));
        MakePlatform(root.transform, "PlatE", new Vector3(22f, 2.4f, 0f), new Vector3(9f, 0.4f, 1f));

        var p = new GameObject("Player");
        p.transform.SetParent(root.transform, false);
        p.transform.position = new Vector3(0f, -1.9f, 0f);
        var psr = p.AddComponent<SpriteRenderer>();
        psr.sprite = GameSprites.Get();
        psr.color = new Color(0.25f, 0.55f, 1f);
        p.transform.localScale = new Vector3(1f, 2f, 1f);
        var pcol = p.AddComponent<BoxCollider2D>();
        pcol.sharedMaterial = new PhysicsMaterial2D("playerSlip") { friction = 0f, bounciness = 0f };
        p.AddComponent<Rigidbody2D>();
        p.AddComponent<ContraPlayer>();
        fc.target = p.transform;

        var sp = new GameObject("Spawner");
        sp.transform.SetParent(root.transform, false);
        sp.AddComponent<ContraSpawner>();

        MakeHint(root.transform);
        Debug.Log("CONTRA_BOOTED");
    }

    static void MakeBox(Transform parent, string name, Vector3 pos, Vector3 size, Color color) {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.transform.position = pos;
        go.transform.localScale = size;
        if (color.a > 0f) {
            var sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = GameSprites.Get();
            sr.color = color;
        }
        go.AddComponent<BoxCollider2D>();
    }

    static void MakePlatform(Transform parent, string name, Vector3 pos, Vector3 size) {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.transform.position = pos;
        go.transform.localScale = size;
        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = GameSprites.Get();
        sr.color = new Color(0.2f, 0.75f, 0.3f);
        go.AddComponent<BoxCollider2D>();
        var eff = go.AddComponent<PlatformEffector2D>();
        eff.useOneWay = true;
        eff.surfaceArc = 90f; // default 180 makes the SIDES solid -> player box catches platform edges and stalls; 90 = top face only
    }

    static void MakeHint(Transform parent) {
        var canvasGo = new GameObject("HintCanvas");
        canvasGo.transform.SetParent(parent, false);
        var canvas = canvasGo.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;
        var txt = canvasGo.AddComponent<Text>();
        txt.color = new Color(1f, 1f, 1f, 0.85f);
        txt.fontSize = 18;
        txt.alignment = TextAnchor.LowerLeft;
        txt.text = "A/D move   Space jump   W/S aim   Shift = aim lock   Z fire   S+Space drop   dodge red";
        Font f = null;
        try { f = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"); } catch (System.Exception) {}
        if (f == null) { try { f = Resources.GetBuiltinResource<Font>("Arial.ttf"); } catch (System.Exception) {} }
        txt.font = f;
        var rt = txt.rectTransform;
        rt.anchorMin = new Vector2(0f, 0f);
        rt.anchorMax = new Vector2(1f, 0f);
        rt.offsetMin = new Vector2(12f, 8f);
        rt.offsetMax = new Vector2(-12f, 44f);
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/ContraEnemy.cs" <<'CSEOF'
using UnityEngine;

public class ContraEnemy : MonoBehaviour {
    public float runSpeed = 3.5f;
    Rigidbody2D rb;
    bool dying;

    void Awake() {
        rb = GetComponent<Rigidbody2D>();
        rb.gravityScale = 4f;
        rb.freezeRotation = true;
    }

    void FixedUpdate() {
        if (dying) return;
        rb.linearVelocity = new Vector2(-runSpeed, rb.linearVelocity.y);
        if (transform.position.x < -38f) Destroy(gameObject);
    }

    public void Die() {
        if (dying) return;
        dying = true;
        var sr = GetComponent<SpriteRenderer>();
        if (sr != null) sr.color = Color.white; // hit flash
        Destroy(gameObject, 0.08f);
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/ContraPlayer.cs" <<'CSEOF'
using UnityEngine;
using UnityEngine.SceneManagement;

public class ContraPlayer : MonoBehaviour {
    public float runSpeed = 7f;
    public float jumpSpeed = 13f;
    public float bulletSpeed = 14f;
    public float fireCooldown = 0.16f;
    public float barrelDist = 0.75f;

    Rigidbody2D rb;
    Collider2D col;
    Transform barrel;
    float fireTimer;
    float faceDir = 1f;
    Vector2 aimDir = Vector2.right;
    bool grounded;
    Collider2D groundCol;
    bool dropping;
    float dropTimer;
    Collider2D dropCol;
    public float dropDuration = 0.25f;
    bool dead;

    void Awake() {
        rb = GetComponent<Rigidbody2D>();
        col = GetComponent<Collider2D>();
        rb.gravityScale = 4f;
        rb.freezeRotation = true;
        var b = new GameObject("Barrel");
        var sr = b.AddComponent<SpriteRenderer>();
        sr.sprite = GameSprites.Get();
        sr.color = Color.yellow;
        b.transform.localScale = new Vector3(0.45f, 0.18f, 1f);
        barrel = b.transform;
        barrel.SetParent(transform.parent, true);
        barrel.position = transform.position;
    }

    void Update() {
        if (dead) return;
        float h = Input.GetAxisRaw("Horizontal");
        float v = Input.GetAxisRaw("Vertical");
        bool locked = Input.GetKey(KeyCode.LeftShift);

        if (h != 0f) faceDir = Mathf.Sign(h);
        if (locked) {
            rb.linearVelocity = new Vector2(0f, rb.linearVelocity.y);
        } else {
            rb.linearVelocity = new Vector2(h * runSpeed, rb.linearVelocity.y);
        }

        grounded = CheckGrounded();
        if (dropping) grounded = false;
        bool dropWish = grounded && Input.GetKey(KeyCode.S) && Input.GetKeyDown(KeyCode.Space);
        if (dropWish && groundCol != null && groundCol.GetComponent<PlatformEffector2D>() != null && !dropping) {
            dropping = true;
            dropTimer = dropDuration;
            dropCol = groundCol;
            Physics2D.IgnoreCollision(col, dropCol, true);
            rb.linearVelocity = new Vector2(rb.linearVelocity.x, -2f);
        } else if (Input.GetKeyDown(KeyCode.Space) && grounded) {
            rb.linearVelocity = new Vector2(rb.linearVelocity.x, jumpSpeed);
        }
        if (dropping) {
            dropTimer -= Time.deltaTime;
            if (dropTimer <= 0f) {
                if (dropCol != null) Physics2D.IgnoreCollision(col, dropCol, false);
                dropCol = null;
                dropping = false;
            }
        }

        Vector2 a = new Vector2(h, v);
        if (a.sqrMagnitude < 0.01f) a = new Vector2(faceDir, 0f);
        if (grounded && !locked && v < 0f && h == 0f) a = new Vector2(faceDir, 0f);
        aimDir = a.normalized;

        float ang = Mathf.Atan2(aimDir.y, aimDir.x) * Mathf.Rad2Deg;
        barrel.position = transform.position + (Vector3)(aimDir * barrelDist);
        barrel.rotation = Quaternion.Euler(0f, 0f, ang);

        fireTimer -= Time.deltaTime;
        bool fireHeld = Input.GetKey(KeyCode.LeftControl) || Input.GetKey(KeyCode.Z);
        if (fireHeld && fireTimer <= 0f) {
            fireTimer = fireCooldown;
            Fire();
        }
    }

    void OnCollisionEnter2D(Collision2D c) {
        if (dead) return;
        if (c.collider != null && c.collider.GetComponent<ContraEnemy>() != null) Die();
    }

    void Die() {
        dead = true;
        var sr = GetComponent<SpriteRenderer>();
        if (sr != null) sr.color = new Color(0.9f, 0.15f, 0.15f);
        if (barrel != null) barrel.gameObject.SetActive(false);
        ContraRestarter.Schedule(0.6f);
    }

    bool CheckGrounded() {
        groundCol = null;
        Vector2 p = transform.position;
        var hits = Physics2D.OverlapBoxAll(p + Vector2.down * 1.05f, new Vector2(0.7f, 0.16f), 0f);
        foreach (var c in hits) {
            if (c == col || c.isTrigger) continue;
            groundCol = c;
            return true;
        }
        return false;
    }

    void Fire() {
        var b = new GameObject("Bullet");
        b.transform.position = barrel.position + (Vector3)(aimDir * 0.25f);
        b.transform.SetParent(transform.parent, true);
        var sr = b.AddComponent<SpriteRenderer>();
        sr.sprite = GameSprites.Get();
        sr.color = Color.white;
        b.transform.localScale = new Vector3(0.25f, 0.25f, 1f);
        var bc = b.AddComponent<BoxCollider2D>();
        bc.isTrigger = true;
        bc.size = Vector2.one;
        var brb = b.AddComponent<Rigidbody2D>();
        brb.gravityScale = 0f;
        brb.linearVelocity = aimDir * bulletSpeed;
        var bl = b.AddComponent<Bullet2D>();
        bl.ignore = col;
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/ContraRestarter.cs" <<'CSEOF'
using UnityEngine;

// Survives the ContraGame root destroy; rebuilds the level once after player death.
// Root renamed BEFORE destroy so Build()'s find-guard passes in the same frame.
public class ContraRestarter : MonoBehaviour {
    float t;
    float delay;

    public static void Schedule(float d) {
        var go = new GameObject("ContraRestarter");
        var r = go.AddComponent<ContraRestarter>();
        r.delay = d;
    }

    void Update() {
        t += Time.deltaTime;
        if (t < delay) return;
        var old = GameObject.Find("ContraGame");
        if (old != null) {
            old.name = "ContraGameOld";
            Object.Destroy(old);
        }
        ContraBoot.Build();
        Destroy(gameObject);
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/ContraSpawner.cs" <<'CSEOF'
using UnityEngine;

public class ContraSpawner : MonoBehaviour {
    public float interval = 2.5f;
    public int maxAlive = 6;
    float timer;

    void Update() {
        timer -= Time.deltaTime;
        if (timer > 0f) return;
        timer = interval;
        if (Object.FindObjectsByType<ContraEnemy>(FindObjectsSortMode.None).Length >= maxAlive) return;
        var cam = Camera.main;
        if (cam == null) return;
        var rootT = GameObject.Find("ContraGame");
        if (rootT == null) return;
        float x = Mathf.Clamp(cam.transform.position.x + 11.5f, -39f, 39f); // just off the visible right edge
        var go = new GameObject("Runner");
        go.transform.position = new Vector3(x, -2.4f, 0f);
        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = GameSprites.Get();
        sr.color = new Color(0.85f, 0.2f, 0.2f);
        go.transform.localScale = new Vector3(0.9f, 1.2f, 1f);
        var bc = go.AddComponent<BoxCollider2D>();
        bc.sharedMaterial = new PhysicsMaterial2D("enemySlip") { friction = 0f, bounciness = 0f };
        go.transform.SetParent(rootT.transform, true);
        go.AddComponent<ContraEnemy>();
    }
}
CSEOF

cat > "$PROJ/Assets/Contra/FollowCam.cs" <<'CSEOF'
using UnityEngine;

public class FollowCam : MonoBehaviour {
    public Transform target;
    public float minX = -26f;
    public float maxX = 26f;
    void LateUpdate() {
        if (target == null) return;
        Vector3 p = transform.position;
        p.x = Mathf.Clamp(target.position.x, minX, maxX);
        transform.position = p;
    }
}
CSEOF


